//! Excluded actual-gallery group feedback preview and bounded native DOM replay.
use dioxus::prelude::*;
use dioxus_ix::*;

#[path = "../../examples/gallery/group_feedback.rs"]
mod gallery_feedback;

#[component]
pub fn GroupFeedbackPreview() -> Element {
    let mut narrow = use_signal(|| false);
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_feedback::STYLES} }
        IxTheme { class: "group-feedback-review",
            h1 { "Group feedback" }
            Button { id: "group-feedback-narrow", variant: ButtonVariant::Secondary,
                onclick: move |_| narrow.toggle(), if narrow() { "Use wide preview" } else { "Use narrow preview" }
            }
            div { id: "group-feedback-frame", style: if narrow() { "width:340px;max-width:100%;min-width:0" } else { "width:960px;max-width:100%;min-width:0" },
                gallery_feedback::GroupFeedbackExample {}
            }
            div { onmounted: move |_| {
                #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
                {
                    let window = window.clone();
                    spawn(async move {
                        let query = crate::dom_query::eval(NATIVE_GROUP_FEEDBACK_CHECK);
                        if let Err(error) = query.send("groupfeedback") {
                            eprintln!("Group feedback native driver failed to start: {error:?}");
                            std::process::exit(1);
                        }
                        match query.join::<serde_json::Value>().await {
                            Ok(result) if result["ok"] == true => {
                                println!("Dioxus native group feedback: {result}");
                                window.close();
                            }
                            result => {
                                eprintln!("Dioxus native group feedback failed: {result:?}");
                                std::process::exit(1);
                            }
                        }
                    });
                    spawn(async move {
                        futures_timer::Delay::new(std::time::Duration::from_secs(30)).await;
                        eprintln!("Group feedback native driver timed out");
                        std::process::exit(1);
                    });
                }
            } }
        }
    }
}

const STYLES: &str = "body{margin:0}.group-feedback-review{box-sizing:border-box;min-height:100vh;padding:24px}.group-feedback-review>h1{font-size:28px;margin:0 0 24px}.group-feedback-review h2{font-size:22px;margin:24px 0 16px}.group-feedback-review p{max-width:72ch;line-height:1.5}#group-feedback-frame{margin-top:24px}@media(max-width:600px){.group-feedback-review{padding:16px}}";

